"use client";

import { useReducedMotion } from "motion/react";
import { type KeyboardEvent, useEffect, useId, useState } from "react";

import { CircleCheckIcon, CircleXIcon, PlayerPauseFilledIcon, PlayerPlayFilledIcon } from "@/components/blocks/parts/icons";
import { NumberTicker } from "@/components/motion/number-ticker";
import { SegmentedControl } from "@/components/motion/segmented-control";
import { Slider } from "@/components/motion/slider";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { Table } from "@/components/ui/table";

import {
  SCATTER_AXES,
  SCATTER_DATA,
  SCATTER_MONTHS,
  SCATTER_TARGET,
  type ScatterChannel,
  type ScatterMonth,
  inTargetZone,
} from "../lib/connected-scatter-data";
import { formatMoney, formatOnePlace, formatWhole } from "../lib/format";
import { ROLL_MONEY, ROLL_ONE_PLACE, ROLL_WHOLE } from "../lib/roll-formats";
import { STATUS_TEXT } from "../lib/status";
import { BlockFrame } from "../parts/block-frame";
import { ScatterPlot } from "./connected-scatter/scatter-plot";

const CHANNELS: { value: ScatterChannel; label: string; noun: string }[] = [
  { value: "all", label: "All", noun: "all channels" },
  { value: "referral", label: "Referrals", noun: "referrals" },
  { value: "search", label: "Search ads", noun: "search ads" },
  { value: "events", label: "Events", noun: "trade events" },
];

const LAST = SCATTER_MONTHS - 1;
// Months the head travels each second while playing.
const SPEED = 1.4;
// Under reduced motion the head steps a whole month at this interval instead of gliding.
const STEP_MS = 900;

const clampMonth = (value: number) => Math.min(LAST, Math.max(0, value));

function describeMonth(month: ScatterMonth, noun: string): string {
  const zone = inTargetZone(month) ? "In target" : "Out of target";
  return `${month.label}, ${noun}: ${formatMoney(month.cost)} to win a clinic, earned back in ${formatOnePlace(month.payback)} months at ${formatMoney(month.revenue)} a month. ${zone}.`;
}

/**
 * Follows two figures through a year at once: what a new clinic costs to
 * win, and how long it takes to earn that back. The path shows the route
 * month by month, and the play control and scrubber move a head along it.
 */
export function ConnectedScatter({ className }: { className?: string }) {
  const [channel, setChannel] = useState<ScatterChannel>("all");
  const [position, setPosition] = useState(LAST);
  const [wantsPlay, setWantsPlay] = useState(false);
  const [hovered, setHovered] = useState<number | null>(null);
  const [scrubbing, setScrubbing] = useState(false);
  const reduceMotion = useReducedMotion();
  const titleId = useId();

  // Play ends by itself at the last month.
  const playing = wantsPlay && position < LAST;

  useEffect(() => {
    if (!playing) return;
    if (reduceMotion) {
      const timer = setInterval(() => setPosition((current) => clampMonth(Math.floor(current) + 1)), STEP_MS);
      return () => clearInterval(timer);
    }
    let frame = 0;
    let before: number | null = null;
    const tick = (now: number) => {
      const elapsed = before === null ? 0 : now - before;
      before = now;
      setPosition((current) => clampMonth(current + (elapsed / 1000) * SPEED));
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [playing, reduceMotion]);

  const months = SCATTER_DATA[channel];
  const noun = CHANNELS.find((item) => item.value === channel)?.noun ?? "all channels";
  const index = Math.round(position);
  const month = months[index] ?? months[LAST]!;
  const inside = inTargetZone(month);
  const ZoneIcon = inside ? CircleCheckIcon : CircleXIcon;

  const scrubTo = (next: number) => {
    setWantsPlay(false);
    setPosition(clampMonth(next));
  };

  const togglePlay = () => {
    if (playing) {
      setWantsPlay(false);
      return;
    }
    if (position >= LAST) setPosition(0);
    setWantsPlay(true);
  };

  // The range input steps a month on arrows and jumps on Home and End. Page keys move three months here.
  const onPageKeys = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key !== "PageUp" && event.key !== "PageDown") return;
    event.preventDefault();
    scrubTo(index + (event.key === "PageUp" ? 3 : -3));
  };

  // The pointer inspects any month. The keyboard inspects the month the scrubber sits on.
  const inspected = hovered ?? (scrubbing && !playing ? index : null);
  const inspectedMonth = inspected === null ? undefined : months[inspected];

  const monthDetails = (at: number) => {
    const row = months[at] ?? month;
    return {
      title: row.label,
      rows: [
        { label: "Cost per clinic", value: formatMoney(row.cost), marker: "bg-chart-1" },
        { label: "Months to earn back", value: formatOnePlace(row.payback) },
      ],
      note: inTargetZone(row) ? "In target" : "Out of target",
    };
  };

  const figures = [
    { label: "Spend", value: Math.round(month.spend), format: ROLL_MONEY },
    { label: "Clinics won", value: Math.round(month.won), format: ROLL_WHOLE },
    { label: "Cost per clinic", value: Math.round(month.cost), format: ROLL_MONEY },
    { label: "Months to earn back", value: month.payback, format: ROLL_ONE_PLACE },
  ];

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Cost of new clinics
          </h2>
          <p className="truncate text-sm text-muted-foreground">
            Target: under {formatMoney(SCATTER_TARGET.cost)}, back in {SCATTER_TARGET.payback} months
          </p>
        </div>
        <SegmentedControl aria-label="Channel" options={CHANNELS} value={channel} onValueChange={setChannel} className="max-w-full overflow-x-auto scroll-fade-effect-x scrollbar-none" />
      </header>

      <div className="grid @3xl:grid-cols-[1fr_18rem]">
        <div className="flex min-w-0 flex-col gap-4 p-5">
          <ScatterPlot
            months={months}
            position={position}
            glide={!playing && !reduceMotion}
            inspected={inspected}
            onInspect={setHovered}
            details={monthDetails}
            label={`Cost per clinic against months to earn it back, month by month, for ${noun}. The axes start at ${formatMoney(SCATTER_AXES.cost.low)} and ${SCATTER_AXES.payback.low} months, not at zero.`}
          />
          <p aria-live="polite" className="sr-only">
            {hovered !== null && inspectedMonth ? describeMonth(inspectedMonth, noun) : ""}
          </p>
          {/* The button keeps one width for Play and Pause, so the slider beside it never moves. */}
          <div className="flex items-end gap-4">
            <Button variant="outline" size="sm" onClick={togglePlay} className="min-h-11 w-24 sm:min-h-8">
              {playing ? <PlayerPauseFilledIcon aria-hidden="true" className="size-4" /> : <PlayerPlayFilledIcon aria-hidden="true" className="size-4" />}
              {playing ? "Pause" : "Play"}
            </Button>
            {/* The wrapper only adds Page keys to the slider inside it, which holds the focus and the role. */}
            <div
              role="presentation"
              onKeyDownCapture={onPageKeys}
              onFocus={(event) => setScrubbing(event.target.matches(":focus-visible"))}
              onBlur={() => setScrubbing(false)}
              className="min-w-0 flex-1"
            >
              <Slider
                label="Month"
                min={0}
                max={LAST}
                step={1}
                value={index}
                onValueChange={scrubTo}
                formatValue={(value) => months[value]?.label ?? ""}
              />
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-4 border-t border-border p-5 @3xl:border-t-0 @3xl:border-l">
          <div className="flex flex-col gap-1">
            <h3 className="truncate text-sm font-medium">{month.label}</h3>
            <p className="flex h-5 items-center gap-1.5 text-sm whitespace-nowrap text-muted-foreground">
              <ZoneIcon aria-hidden="true" className={cn("size-4", inside ? STATUS_TEXT.good : STATUS_TEXT.bad)} />
              <span className={inside ? STATUS_TEXT.good : STATUS_TEXT.bad}>{inside ? "In target" : "Out of target"}</span>
            </p>
          </div>
          <dl className="grid grid-cols-2 gap-x-6 gap-y-4 @3xl:grid-cols-1">
            {figures.map((figure) => (
              <div key={figure.label} className="flex min-w-0 flex-col gap-0.5">
                <dt className="truncate text-sm text-muted-foreground">{figure.label}</dt>
                <dd className="h-8 text-2xl font-semibold tracking-tight tabular-nums">
                  <NumberTicker value={figure.value} format={figure.format} />
                </dd>
              </div>
            ))}
          </dl>
          <p aria-live={playing ? "off" : "polite"} className="sr-only">
            {describeMonth(month, noun)}
          </p>
        </div>
      </div>

      <div className="sr-only">
      <Table>
        <caption>Each month for {noun}</caption>
        <thead>
          <tr>
            <th scope="col">Month</th>
            <th scope="col">Spend</th>
            <th scope="col">Clinics won</th>
            <th scope="col">Cost per clinic</th>
            <th scope="col">Months to earn back</th>
            <th scope="col">Target</th>
          </tr>
        </thead>
        <tbody>
          {months.map((row) => (
            <tr key={row.label}>
              <th scope="row">{row.label}</th>
              <td>{formatMoney(row.spend)}</td>
              <td>{formatWhole(row.won)}</td>
              <td>{formatMoney(row.cost)}</td>
              <td>{formatOnePlace(row.payback)}</td>
              <td>{inTargetZone(row) ? "In target" : "Out of target"}</td>
            </tr>
          ))}
        </tbody>
      </Table>
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
export const ArrowDownIcon = packIcon("arrow-up", "rotate-180");
/** An arrow that points left, from the chosen icon pack. */
