"use client";

import { motion, type Transition } from "motion/react";
import type { PointerEvent } from "react";

import { cn } from "@/lib/utils";

import {
  SCATTER_AXES,
  SCATTER_TARGET,
  scatterAlong,
  type ScatterMonth,
  type ScatterPoint,
  scatterPoint,
  scatterPointAt,
} from "../../lib/connected-scatter-data";
import { formatMoney } from "../../lib/format";
import { STATUS_SURFACE, STATUS_TEXT } from "../../lib/status";
import { PointTip, type PointTipProps } from "../../parts/point-tip";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for the connected scatterplot. */
export interface ScatterPlotProps {
  months: ScatterMonth[];
  /** The head's place in time, as a month index that may sit between two months while playing. */
  position: number;
  /** False while playing or under reduced motion, so the paths follow at once. */
  glide: boolean;
  /** The month whose details show in the card, or null when no month is inspected. */
  inspected: number | null;
  /** Called with the month nearest the pointer, and with null when the pointer leaves. */
  onInspect: (index: number | null) => void;
  /** The details shown in the card beside the inspected month. */
  details: (index: number) => Pick<PointTipProps, "title" | "rows" | "note">;
  /** Names the drawing for screen readers, and says where the axes start. */
  label: string;
  className?: string;
}

// Critically damped: 2 * sqrt(260) is about 32.
const MORPH: Transition = { type: "spring", stiffness: 260, damping: 32, mass: 1 };
const INSTANT: Transition = { duration: 0 };

const COST_TICKS = SCATTER_AXES.cost.ticks;
const PAYBACK_TICKS = [...SCATTER_AXES.payback.ticks].reverse();
const ZONE = {
  width: scatterAlong("cost", SCATTER_TARGET.cost),
  top: 100 - scatterAlong("payback", SCATTER_TARGET.payback),
};

const pair = (point: ScatterPoint) => `${point.x.toFixed(2)} ${point.y.toFixed(2)}`;
const line = (points: ScatterPoint[]) => points.map((point, index) => `${index === 0 ? "M" : "L"}${pair(point)}`).join(" ");
// A zero-length segment with a round cap draws a round dot that keeps its shape when the box stretches.
const dots = (points: ScatterPoint[]) => points.map((point) => `M${pair(point)} L${pair(point)}`).join(" ");

/**
 * Twelve months as points joined in time order. The dashed line is the whole
 * year, the solid line is the part up to the head, and the shaded corner is
 * the target zone. The month nearest the pointer gets a ring and a card with
 * its figures. It is one image to a screen reader: its label names it and
 * says the axes do not start at zero, and the figures beside it carry the text.
 */
export function ScatterPlot({ months, position, glide, inspected, onInspect, details, label, className }: ScatterPlotProps) {
  const transition = glide ? MORPH : INSTANT;
  const all = months.map(scatterPoint);
  const head = scatterPointAt(months, position);
  // Months past the head fold onto it, so every path keeps the same shape and can morph.
  const travelled = all.map((point, index) => (index <= position ? point : head));
  const first = all[0];
  const last = all[all.length - 1];
  const marked = inspected === null ? undefined : all[inspected];

  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const box = event.currentTarget.getBoundingClientRect();
    if (box.width === 0 || box.height === 0) return;
    const x = ((event.clientX - box.left) / box.width) * 100;
    const y = ((event.clientY - box.top) / box.height) * 100;
    let nearest: number | null = null;
    let gap = Number.POSITIVE_INFINITY;
    all.forEach((point, index) => {
      // Distance on screen, since the box stretches each axis by a different amount.
      const distance = Math.hypot(((point.x - x) / 100) * box.width, ((point.y - y) / 100) * box.height);
      if (distance < gap) {
        gap = distance;
        nearest = index;
      }
    });
    onInspect(nearest);
  };
  // SAFETY: a const assertion only, so the SVG attribute literals keep their exact types.
  const shared = { initial: false, transition, fill: "none", vectorEffect: "non-scaling-stroke", strokeLinecap: "round", strokeLinejoin: "round" } as const;

  return (
    <div role="img" aria-label={label} className={cn("flex flex-col gap-2", className)}>
      <p className="text-xs text-muted-foreground">Months to earn back</p>
      <div className="flex gap-3">
        <div className="flex w-5 shrink-0 flex-col justify-between text-right text-xs tabular-nums text-muted-foreground">
          {PAYBACK_TICKS.map((tick) => (
            <span key={tick} className="-my-2 leading-4">
              {tick}
            </span>
          ))}
        </div>
        <div
          onPointerDown={onPointerMove}
          onPointerMove={onPointerMove}
          // A finger leaves when it lifts, so only a mouse clears the point on the way out.
          onPointerLeave={(event) => {
            if (event.pointerType === "mouse") onInspect(null);
          }}
          className="relative h-72 min-w-0 flex-1 cursor-crosshair touch-pan-y @2xl:h-96"
        >
          <div className="absolute inset-0 flex flex-col justify-between">
            {PAYBACK_TICKS.map((tick) => (
              <span key={tick} className="h-px w-full bg-border/60" />
            ))}
          </div>
          <div
            className={cn("w-(--w) top-(--y) absolute bottom-0 left-0 rounded-tr-md border-t border-r border-dashed border-current", STATUS_SURFACE.good, STATUS_TEXT.good)}
            style={
              // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
              { "--w": `${ZONE.width}%`, "--y": `${ZONE.top}%` } as VarStyle
            }
          >
            <span className="absolute bottom-1.5 left-2 text-xs font-medium">Target zone</span>
          </div>
          <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="absolute inset-0 size-full overflow-visible">
            <motion.path {...shared} animate={{ d: line(all) }} strokeWidth="1.5" strokeDasharray="3 4" className="stroke-muted-foreground/60" />
            <motion.path {...shared} animate={{ d: dots(all) }} strokeWidth="6" className="stroke-muted-foreground/60" />
            <motion.path {...shared} animate={{ d: line(travelled) }} strokeWidth="2" className="stroke-chart-1" />
            <motion.path {...shared} animate={{ d: dots(travelled) }} strokeWidth="7" className="stroke-chart-1" />
            <motion.path {...shared} animate={{ d: dots([head]) }} strokeWidth="17" className="stroke-card" />
            <motion.path {...shared} animate={{ d: dots([head]) }} strokeWidth="12" className="stroke-chart-1" />
          </svg>
          {[first, last].map((point, index) =>
            point ? (
              <span
                key={index === 0 ? "start" : "end"}
                className="left-(--x) top-(--y) absolute -translate-x-1/2 translate-y-2 rounded-sm bg-card/80 px-1 text-xs whitespace-nowrap text-muted-foreground"
                style={
                  // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                  { "--x": `${point.x}%`, "--y": `${point.y}%` } as VarStyle
                }
              >
                {index === 0 ? "Start" : "Latest"}
              </span>
            ) : null,
          )}
          {inspected !== null && marked ? (
            <>
              <span
                className="left-(--x) top-(--y) pointer-events-none absolute size-4 -translate-1/2 rounded-full border-2 border-chart-1 bg-card shadow-sm"
                style={
                  // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                  { "--x": `${marked.x}%`, "--y": `${marked.y}%` } as VarStyle
                }
              />
              <PointTip x={marked.x} y={marked.y} {...details(inspected)} />
            </>
          ) : null}
        </div>
      </div>
      <div className="ml-8 flex justify-between text-xs tabular-nums text-muted-foreground">
        {COST_TICKS.map((tick) => (
          <span key={tick}>{formatMoney(tick)}</span>
        ))}
      </div>
      <p className="ml-8 text-xs text-muted-foreground">Cost per clinic</p>
    </div>
  );
}

import { cn } from "@/lib/utils";

import type { VarStyle } from "@/components/blocks/lib/css-vars";
import { RollingText } from "./rolling-text";

/** One line of a point's details. */
export interface PointTipRow {
  label: string;
  value: string;
  /** A class that colours the row's marker, such as `bg-chart-1`. Omit for a row with no series. */
  marker?: string;
  /** Draws the marker as a dashed line, for an earlier period. */
  dashed?: boolean;
}

/** Props for the card that shows one point's details. */
export interface PointTipProps {
  /** Where the point sits in its plot, from 0 to 100 on each axis, measured from the top left. */
  x: number;
  y: number;
  title: string;
  rows: PointTipRow[];
  /** A closing line, such as the difference between two rows. */
  note?: string;
  className?: string;
}

/**
 * A small card beside an inspected point. It sits on the side of the point
 * with more room and stays inside the plot. In a plot narrower than the card
 * and the point together, it may cover the point rather than be cut off.
 * The digits of each value roll to the next point's figure as the point changes.
 * The card blurs what is behind it, so a design system with a see-through popover stays legible.
 * It is decorative for screen readers: the plot's live readout says the same.
 */
export function PointTip({ x, y, title, rows, note, className }: PointTipProps) {
  const onLeft = x > 55;
  return (
    <div
      aria-hidden="true"
      className={cn("pointer-events-none absolute top-(--y) z-10", onLeft ? "right-(--side)" : "left-(--side)", className)}
      style={
        // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
        {
          // The card hangs one rem from the point, but never past the plot's edge: 14rem is its widest.
          "--side": `min(calc(${onLeft ? 100 - x : x}% + 1rem), calc(100% - 14rem))`,
          "--y": `${Math.min(78, Math.max(22, y))}%`,
        } as VarStyle
      }
    >
      <div
        className={cn(
          "flex w-max max-w-56 -translate-y-1/2 flex-col gap-1.5 rounded-xl border border-border bg-popover px-3 py-2 text-popover-foreground shadow-lg backdrop-blur-md",
        )}
      >
        <span className="text-xs text-muted-foreground">{title}</span>
        {rows.map((row) => (
          <span key={row.label} className="flex items-center justify-between gap-6 text-sm">
            <span className="flex items-center gap-2 text-muted-foreground">
              {row.marker ? (
                <span className={cn("h-0.5 w-3 rounded-full", row.dashed ? "border-t border-dashed border-current" : row.marker)} />
              ) : null}
              {row.label}
            </span>
            <RollingText text={row.value} className="font-medium" />
          </span>
        ))}
        {note ? <span className="border-t border-border pt-1.5 text-xs text-muted-foreground">{note}</span> : null}
      </div>
    </div>
  );
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}
